#include "tensor_plan_diff_spike.h"
#include <errno.h>
static char*read_trace(const char*path,char*error,size_t error_n){FILE*f=fopen(path,"rb");if(!f){snprintf(error,error_n,"%s: %s",path,strerror(errno));return NULL;}if(fseek(f,0,SEEK_END)){fclose(f);return NULL;}long n=ftell(f);if(n<0||n>DIFF_MAX_FILE||fseek(f,0,SEEK_SET)){fclose(f);snprintf(error,error_n,"%s: trace too large",path);return NULL;}char*p=malloc((size_t)n+1);if(!p){fclose(f);return NULL;}if(fread(p,1,(size_t)n,f)!=(size_t)n||fclose(f)){free(p);return NULL;}p[n]=0;return p;}
int run_plan_diff(int argc,char**argv){if(argc<2||argc>3){fprintf(stderr,"usage: tensorctl plan diff PLAN_A.tsv PLAN_B.tsv [--machine]\n");return 2;}int machine=argc==3&&!strcmp(argv[2],"--machine");if(argc==3&&!machine)return 2;char error[256],*ta=read_trace(argv[0],error,sizeof error);if(!ta){fprintf(stderr,"tensorctl plan diff: %s\n",error);return 1;}char*tb=read_trace(argv[1],error,sizeof error);if(!tb){fprintf(stderr,"tensorctl plan diff: %s\n",error);free(ta);return 1;}ParsedTrace a,b;if(parse_trace_text(ta,&a,error,sizeof error)||parse_trace_text(tb,&b,error,sizeof error)){fprintf(stderr,"tensorctl plan diff: %s\n",error);free(ta);free(tb);return 1;}int changes=diff_traces(&a,&b,machine?NULL:stdout,machine?stdout:NULL);free(ta);free(tb);return changes<0?1:0;}
